  1→package agents
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"os"
  8→	"os/exec"
  9→	"path/filepath"
 10→	"strings"
 11→	"time"
 12→)
 13→
 14→func init() {
 15→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
 16→		return
 17→	}
 18→	Register(&CursorCLI{})
 19→}
 20→
 21→// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
 22→// The CLI binary is called "agent" and uses Cursor's hooks system via
 23→// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
 24→//
 25→// All E2E interactions use interactive (tmux) mode so that the full hook
 26→// lifecycle fires (sessionStart, beforeSubmitPrompt, stop, sessionEnd).
 27→// Headless (-p) mode skips beforeSubmitPrompt and stop hooks.
 28→type CursorCLI struct{}
 29→
 30→func (a *CursorCLI) Name() string               { return "cursor-cli" }
 31→func (a *CursorCLI) Binary() string             { return "agent" }
 32→func (a *CursorCLI) EntireAgent() string        { return "cursor" }
 33→func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }
 34→
 35→// PromptPattern returns a regex matching the Cursor CLI's TUI input prompt.
 36→// The CLI shows a styled input box with placeholder text when ready for input.
 37→func (a *CursorCLI) PromptPattern() string { return `/ commands` }
 38→
 39→func (a *CursorCLI) IsTransientError(out Output, err error) bool {
 40→	if err == nil {
 41→		return false
 42→	}
 43→	if errors.Is(err, context.DeadlineExceeded) {
 44→		return true
 45→	}
 46→	combined := out.Stdout + out.Stderr
 47→	for _, p := range []string{
 48→		"overloaded",
 49→		"rate limit",
 50→		"429",
 51→		"503",
 52→		"529",
 53→		"ECONNRESET",
 54→		"ETIMEDOUT",
 55→		"server error",
 56→		"Internal Server Error",
 57→	} {
 58→		if strings.Contains(combined, p) {
 59→			return true
 60→		}
 61→	}
 62→	return false
 63→}
 64→
 65→func (a *CursorCLI) Bootstrap() error {
 66→	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
 67→	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
 68→	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
 69→		return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
 70→	}
 71→	return nil
 72→}
 73→
 74→// cursorConfigDir creates an isolated per-session config directory for the
 75→// Cursor CLI. Each session gets its own XDG_CONFIG_HOME so that parallel tests
 76→// don't race on the shared ~/.config/cursor/cli-config.json file.
 77→// The directory is pre-seeded with an empty cli-config.json to avoid the
 78→// atomic temp-file rename that triggers the ENOENT race.
 79→func cursorConfigDir() (string, error) {
 80→	tmp, err := os.MkdirTemp("", "cursor-e2e-config-*")
 81→	if err != nil {
 82→		return "", fmt.Errorf("create temp config dir: %w", err)
 83→	}
 84→	cursorDir := filepath.Join(tmp, "cursor")
 85→	if err := os.MkdirAll(cursorDir, 0o755); err != nil {
 86→		return "", fmt.Errorf("mkdir cursor config: %w", err)
 87→	}
 88→	if err := os.WriteFile(filepath.Join(cursorDir, "cli-config.json"), []byte("{}"), 0o644); err != nil {
 89→		return "", fmt.Errorf("seed cli-config.json: %w", err)
 90→	}
 91→	return tmp, nil
 92→}
 93→
 94→func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 95→	cfg := &runConfig{}
 96→	for _, o := range opts {
 97→		o(cfg)
 98→	}
 99→
100→	timeout := 90 * time.Second
101→	if cfg.PromptTimeout > 0 {
102→		timeout = cfg.PromptTimeout
103→	}
104→
105→	displayCmd := a.Binary() + " --force --workspace " + dir + " (interactive prompt: " + prompt + ")"
106→
107→	// Start an interactive tmux session so all hooks fire
108→	// (beforeSubmitPrompt and stop don't fire in headless -p mode).
109→	s, err := a.startInteractiveSession(dir)
110→	if err != nil {
111→		return Output{Command: displayCmd, ExitCode: -1},
112→			fmt.Errorf("start interactive session: %w", err)
113→	}
114→	defer s.Close()
115→
116→	// Wait for trust dialog and accept it.
117→	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
118→		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
119→	}
120→
121→	// Wait for the TUI to be ready.
122→	if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
123→		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
124→			fmt.Errorf("waiting for startup prompt: %w", err)
125→	}
126→
127→	// Send the prompt.
128→	if err := s.Send(prompt); err != nil {
129→		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
130→			fmt.Errorf("sending prompt: %w", err)
131→	}
132→
133→	// Wait for the "Add a follow-up" text that only appears after the agent
134→	// finishes processing. We cannot reuse PromptPattern() ("/ commands")
135→	// because that text is always visible in the status bar — even during
136→	// the "Thinking" phase — causing WaitFor to settle prematurely when the
137→	// model takes >2s to start producing visible output.
138→	content, waitErr := s.WaitFor(`Add a follow-up`, timeout)
139→	if waitErr != nil {
140→		// Check for deadline exceeded to allow transient error detection.
141→		if ctx.Err() == context.DeadlineExceeded {
142→			waitErr = fmt.Errorf("%w: %w", waitErr, context.DeadlineExceeded)
143→		}
144→		return Output{Command: displayCmd, Stdout: content, ExitCode: -1}, waitErr
145→	}
146→
147→	return Output{Command: displayCmd, Stdout: content, ExitCode: 0}, nil
148→}
149→
150→func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
151→	s, err := a.startInteractiveSession(dir)
152→	if err != nil {
153→		return nil, err
154→	}
155→
156→	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
157→		_ = s.Close()
158→		return nil, err
159→	}
160→
161→	// Wait for the TUI to be ready (input prompt).
162→	if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
163→		_ = s.Close()
164→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
165→	}
166→	s.stableAtSend = ""
167→
168→	return s, nil
169→}
170→
171→// startInteractiveSession creates a new tmux session running the Cursor CLI
172→// in interactive mode (no -p flag) so all hooks fire.
173→func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
174→	// Resolve to absolute path so tmux can find the binary even if its
175→	// shell doesn't inherit the test process's PATH (common on CI).
176→	bin, err := exec.LookPath(a.Binary())
177→	if err != nil {
178→		return nil, fmt.Errorf("agent binary not found: %w", err)
179→	}
180→
181→	// Create an isolated config directory for this session so parallel tests
182→	// don't race on the shared ~/.config/cursor/cli-config.json file.
183→	configDir, err := cursorConfigDir()
184→	if err != nil {
185→		return nil, fmt.Errorf("create cursor config dir: %w", err)
186→	}
187→
188→	// Build env-wrapped command so the tmux session inherits critical env vars.
189→	// tmux starts a new shell that doesn't inherit Go's os.Environ().
190→	var envArgs []string
191→	for _, key := range []string{"CURSOR_API_KEY", "PATH", "TERM"} {
192→		if v := os.Getenv(key); v != "" {
193→			envArgs = append(envArgs, key+"="+v)
194→		}
195→	}
196→	// Point XDG_CONFIG_HOME to our isolated dir so cursor writes its config
197→	// there instead of ~/.config/cursor/. Also override HOME as a fallback
198→	// since cursor may derive the config path from HOME on some platforms.
199→	envArgs = append(envArgs, "XDG_CONFIG_HOME="+configDir)
200→	envArgs = append(envArgs, "HOME="+configDir)
201→
202→	args := append([]string{"env"}, envArgs...)
203→	args = append(args, bin, "--force", "--workspace", dir)
204→
205→	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
206→	unset := []string{"CI"}
207→	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
208→	if err != nil {
209→		_ = os.RemoveAll(configDir)
210→		return nil, err
211→	}
212→	s.OnClose(func() { _ = os.RemoveAll(configDir) })
213→	return s, nil
214→}
215→
216→// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
217→// and presses "a" to accept it. The dialog only shows on the first launch in
218→// a workspace — subsequent sessions in the same directory skip it.
219→func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
220→	// Race: either the trust dialog or the input prompt will appear first.
221→	// Use a short timeout to check for the trust dialog without blocking
222→	// too long if the workspace is already trusted.
223→	content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 30*time.Second)
224→	if err != nil {
225→		return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
226→	}
227→	if strings.Contains(content, "Trust this workspace") {
228→		if err := s.SendKeys("a"); err != nil {
229→			return fmt.Errorf("accepting trust dialog: %w", err)
230→		}
231→	}
232→	return nil
233→}
